.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
base<-read.csv('outputs/stage6_foxp2_gnomad_narrow_variants.csv');d<-read.csv('outputs/stage6_gong_foxp2_factor_aligned.csv');sel<-match(d$rs,base$rs);stopifnot(!anyNA(sel),!anyDuplicated(sel));p0<-nrow(base);p<-nrow(d)
readR<-function(pop){M<-matrix(readBin(paste0('work/stage6_foxp2_gnomad_',pop,'_narrow_ld.bin'),'double',n=p0*p0,size=8,endian='little'),p0,p0);M<-M[sel,sel];dimnames(M)<-list(d$rs,d$rs);stopifnot(min(eigen(M,symmetric=TRUE,only.values=TRUE)$values)> -1e-8);M};Rn<-readR('nfe');Rf<-readR('fin')
traits<-c('MSKdg','MVP_insomnia','FinnGen_HFRS');ns<-c(1131013,253769,500737);zs<-list(d$factor_z_anchor,d$mvp_z_anchor,d$hfrs_z_anchor);fits<-list();diag<-list();members<-list()
for(i in seq_along(traits)){M<-if(traits[i]=='FinnGen_HFRS')Rf else Rn;z<-zs[[i]];names(z)<-d$rs;s<-estimate_s_rss(z,M,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=M,n=ns[i],L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[traits[i]]]<-f;diag[[i]]<-data.frame(trait=traits[i],n=ns[i],n_variants=p,lambda=s,converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip));if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){ii<-f$sets$cs[[k]];members[[length(members)+1]]<-data.frame(trait=traits[i],component=f$sets$cs_index[k],rs=d$rs[ii],pip=f$pip[ii])};cat(traits[i],'sets',length(f$sets$cs),'lambda',s,'converged',f$converged,'\n');flush.console()}
# Exploratory effective-N sensitivity for the Genomic SEM factor; not validation of a suitable likelihood.
for(n in c(100000,500000)){z<-d$factor_z_anchor;names(z)<-d$rs;set.seed(42);f<-susie_rss(z=z,R=Rn,n=n,L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);key<-sprintf('MSKdg_n%.0f',n);fits[[key]]<-f;diag[[length(diag)+1]]<-data.frame(trait=key,n=n,n_variants=p,lambda=estimate_s_rss(z,Rn,n=n),converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip));cat(key,'sets',length(f$sets$cs),'converged',f$converged,'\n');flush.console()}
write.csv(do.call(rbind,diag),'outputs/stage6_gong_foxp2_factor_susie_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_gong_foxp2_factor_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_gong_foxp2_factor_susie_fits.rds');out<-list()
for(a in c('MSKdg','MSKdg_n100000','MSKdg_n500000'))for(b in c('MVP_insomnia','FinnGen_HFRS')){f<-fits[[a]];g<-fits[[b]];if(!f$converged||!g$converged||!length(f$sets$cs)||!length(g$sets$cs))next;for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(f,g,p1=1e-4,p2=1e-4,p12=p12)$summary);x$trait1<-a;x$trait2<-b;x$p12<-p12;out[[length(out)+1]]<-x}}
f<-fits[['MVP_insomnia']];g<-fits[['FinnGen_HFRS']];if(length(f$sets$cs)&&length(g$sets$cs))for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(f,g,p1=1e-4,p2=1e-4,p12=p12)$summary);x$trait1<-'MVP_insomnia';x$trait2<-'FinnGen_HFRS';x$p12<-p12;out[[length(out)+1]]<-x}
if(length(out))write.csv(do.call(rbind,out),'outputs/stage6_gong_foxp2_factor_susie_coloc.csv',row.names=FALSE)
